const app=document.getElementById('app'),socket=io();
let quiz=null,role=null,code=null,locked=false,timer=null,currentQuestionIndex=-1,dragQuestionIndex=null;
let lastGameFinished=null;
const COLORS=['#e84855','#f4b942','#2e9de0','#8b5cf6'];
const AVATARS=['🦊','🐱','🐶','🐼','🐸','🐯','🐰','🐨','🦄','🐙','👾','🤖','sub1','sub2','sub3','sub4','sub5','sub6','sub7','sub8','sub9','sub10','sub11','sub12'];
const PIXEL_AVATARS=new Set(['sub1','sub2','sub3','sub4','sub5','sub6','sub7','sub8','sub9','sub10','sub11','sub12']);
const AVATAR_NAMES={sub1:'핑크 고양이',sub2:'블루 테크',sub3:'퍼플 고딕',sub4:'골든 아가씨',sub5:'흑발 다크',sub6:'민트 소녀',sub7:'은발 아이스',sub8:'철갑 여기사',sub9:'사이버 보이',sub10:'붉은 악마',sub11:'보라 마녀',sub12:'핑크 아이돌'};
let playerAvatar=sessionStorage.getItem('quiz-live-avatar')||'🦊';
if(!AVATARS.includes(playerAvatar))playerAvatar='🦊';
function avatarMarkup(a,cls='avatar-face'){const v=AVATARS.includes(a)?a:'🦊';return PIXEL_AVATARS.has(v)?`<img class="${cls}" src="/avatars/${v}.png" alt="${esc(AVATAR_NAMES[v]||'도트 아바타')}" title="${esc(AVATAR_NAMES[v]||'도트 아바타')}">`:`<span class="${cls} avatar-emoji">${esc(v)}</span>`}
function avatarPicker(){return `<div class="avatar-picker"><label>아바타 <small>24종 · 마음에 드는 아이콘을 골라보세요</small></label><div class="avatar-grid">${AVATARS.map(a=>`<button type="button" class="avatar-choice ${a===playerAvatar?'selected':''} ${PIXEL_AVATARS.has(a)?'pixel-avatar':''}" data-avatar="${a}" title="${esc(AVATAR_NAMES[a]||a)}" onclick="selectAvatar(this, '${a}')">${avatarMarkup(a,'avatar-choice-img')}</button>`).join('')}</div></div>`}
function selectAvatar(el,a){if(!AVATARS.includes(a))a='🦊';playerAvatar=a;document.querySelectorAll('.avatar-choice').forEach(x=>x.classList.toggle('selected',x===el));sessionStorage.setItem('quiz-live-avatar',a)}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function getLocalQuizzes(){try{return JSON.parse(localStorage.getItem('quiz-live-local')||'[]')}catch{return []}}
function saveLocalQuiz(q,token){const list=getLocalQuizzes().filter(x=>x.id!==q.id);const lightweight=JSON.parse(JSON.stringify(q));lightweight.questions=(lightweight.questions||[]).map(x=>({...x,audioUrl:'',audioName:x.audioName||''}));list.unshift({id:q.id,title:q.title,quiz:lightweight,token,updatedAt:Date.now()});try{localStorage.setItem('quiz-live-local',JSON.stringify(list.slice(0,50)))}catch(e){localStorage.removeItem('quiz-live-local');localStorage.setItem('quiz-live-local',JSON.stringify(list.slice(0,10)))}}
function removeLocalQuiz(id){const list=getLocalQuizzes().filter(x=>x.id!==id);localStorage.setItem('quiz-live-local',JSON.stringify(list))}
function home(){document.getElementById('eliminatedBanner')?.remove();applyTheme(null);const saved=getLocalQuizzes();app.innerHTML=`<div class="wrap"><div class="hero"><div class="logo">QUIZ <span>LIVE</span></div><p class="muted">누구나 만들고 친구와 바로 즐기는 실시간 퀴즈</p></div><div class="grid home-grid"><div class="card create-card"><div><span class="home-card-icon">＋</span><h2>🎨 퀴즈 만들기</h2><p class="muted">나만의 퀴즈를 만들고 친구들과 바로 즐겨보세요.</p></div><button onclick="builder()">바로 만들기</button></div><div class="card join-card"><h2>🎮 참가하기</h2><input id="jc" placeholder="방 코드" inputmode="numeric" maxlength="6"><div class="field"><input id="jn" placeholder="닉네임" maxlength="20"></div>${avatarPicker()}<button onclick="join()">참가</button></div></div>${saved.length?`<div class="card"><h2>💾 내 컴퓨터에 저장된 퀴즈</h2><p class="muted">이 브라우저의 기록이 삭제되지 않는 동안 언제든 다시 관리할 수 있어요.</p><div class="saved-list">${saved.map(x=>`<div class="saved-item"><div class="saved-info"><b>${esc(x.title)}</b><small>${new Date(x.updatedAt).toLocaleString('ko-KR')}</small></div><div class="saved-actions"><button class="secondary" onclick="openManage('${esc(x.id)}','${esc(x.token)}')">관리/수정</button><button onclick="makeRoomForQuiz('${esc(x.id)}')">방 만들기</button></div></div>`).join('')}</div></div>`:''}</div>`}

home();function reconnectPlayer(){const rr=sessionStorage.getItem('quiz-live-room'),nn=sessionStorage.getItem('quiz-live-nickname'),rt=sessionStorage.getItem('quiz-live-reconnect');if(rr&&nn){role='player';code=rr;socket.emit('player:join',{code:rr,nickname:nn,avatar:playerAvatar,reconnectToken:rt||''})}}socket.on('connect',()=>{if(role==='player')reconnectPlayer()});
function nq(){return{type:'choice',prompt:'',options:['','','',''],answer:'',timeLimit:15,revealEnabled:true,revealSeconds:5,videoId:'',audioUrl:'',audioName:'',mediaType:'',start:0,end:15,showVideo:true,fever:false,platinum:false,allowAnswerChange:false,waitFullTime:true,imageUrl:'',highRisk:false,raidEnabled:false,raidThresholdType:'count',raidThreshold:2}}
function normalizeQuizModes(q){if(q.mode==='survival')q.mode='death';q.mode=['normal','death','speedrun','team'].includes(q.mode)?q.mode:'normal';q.comboEnabled=q.mode==='speedrun'?false:!!q.comboEnabled;q.questions=(q.questions||[]).map(x=>({...nq(),...x}));applyModeRestrictions(q);return q}
function applyModeRestrictions(q){if(!q||!Array.isArray(q.questions))return q;for(const x of q.questions){if(x.raidEnabled&&x.highRisk)x.highRisk=false;if(q.mode==='speedrun'){q.comboEnabled=false;x.waitFullTime=false;x.highRisk=false;x.raidEnabled=false}else if(q.mode==='team'){x.raidEnabled=false}else if(q.mode==='death'){x.highRisk=false;x.raidEnabled=false}if(x.raidEnabled&&q.mode==='normal'){x.type='choice';x.options=Array.from({length:8},(_,k)=>x.options?.[k]||'')}else if(!x.raidEnabled&&x.type==='choice'&&(x.options||[]).length>4){x.options=Array.from({length:4},(_,k)=>x.options?.[k]||'');if(Array.isArray(x.answer))x.answer=x.answer[0]||''}}return q}
function raidAllowed(){return !!quiz&&quiz.mode==='normal'}
function highRiskAllowed(){return !!quiz&&['normal','team'].includes(quiz.mode)}
function toggleHighRisk(i,on){const q=quiz.questions[i];q.highRisk=!!on;if(on)q.raidEnabled=false;drawB()}
function toggleRaid(i,on){const q=quiz.questions[i];q.raidEnabled=!!on;if(on){q.highRisk=false;q.type='choice';q.options=Array.from({length:8},(_,k)=>q.options?.[k]||'');q.answer=q.answer||''}else{q.options=Array.from({length:4},(_,k)=>q.options?.[k]||'');q.answer=Array.isArray(q.answer)?q.answer[0]||'':q.answer}drawB()}
function modeLabel(m){return m==='death'||m==='survival'?'☠️ 데스 모드':m==='speedrun'?'⚡ 스피드런':m==='team'?'🔴🔵 팀':'🎯 일반'}
function modeHelp(m){if(m==='death'||m==='survival')return '오답·미응답이면 탈락합니다. 마지막 생존자가 1등입니다.';if(m==='speedrun')return '답을 제출하는 즉시 다음 문제로 이동합니다. 정확하고 빠르게 푸는 사람이 승리합니다.';if(m==='team')return 'RED/BLUE로 자동 균등 배정됩니다. 우리 팀원의 정확도를 확인합니다.';return '모두 같은 문제를 함께 풀고 정답 공개 후 다음 문제로 진행합니다.'}
function showInfoPopup(title,text){const old=document.getElementById('infoPopup');if(old)old.remove();const d=document.createElement('div');d.id='infoPopup';d.className='info-popup-backdrop';d.innerHTML=`<div class="info-popup" role="dialog" aria-modal="true"><button class="info-popup-close" onclick="document.getElementById('infoPopup')?.remove()">×</button><h3>${esc(title)}</h3><p>${esc(text)}</p><button onclick="document.getElementById('infoPopup')?.remove()">확인</button></div>`;d.onclick=e=>{if(e.target===d)d.remove()};document.body.appendChild(d)}
function modeHelpMarkup(title,text){return `<span class="help-tip"><button type="button" class="help-button" data-title="${esc(title)}" data-text="${esc(text)}" onclick="event.stopPropagation();showInfoPopup(this.dataset.title,this.dataset.text)">?</button><span class="help-bubble">${esc(text)}</span></span>`}
function builder(q={title:'',theme:{background:'',accent:'#795cff',colors:[...COLORS]},mode:'normal',comboEnabled:false,questions:[nq()]}){
  quiz=normalizeQuizModes(q); quiz.theme=quiz.theme||{}; applyTheme(quiz.theme); quiz.theme.colors=(quiz.theme.colors&&quiz.theme.colors.length===4)?quiz.theme.colors:[...COLORS]; quiz.theme.accent=quiz.theme.accent||'#795cff'; drawB()
}
function syncBuilderMeta(){if(!quiz)return;const title=document.getElementById('title');if(title)quiz.title=title.value;quiz.theme=quiz.theme||{background:'',colors:[...COLORS],accent:'#795cff'};}
function applyTheme(theme){const bg=theme?.background||'';document.body.style.backgroundImage=bg?`linear-gradient(#10121acc,#10121acc),url("${String(bg).replace(/"/g,'')}")`:'';document.body.style.backgroundSize=bg?'cover':'';document.body.style.backgroundPosition=bg?'center':'';document.body.style.backgroundAttachment=bg?'fixed':'';document.body.style.backgroundRepeat=bg?'no-repeat':'';}
async function uploadImageFile(file){if(!file)return null;if(!/^image\/(jpeg|png|webp|gif)$/i.test(file.type))throw new Error('JPG/PNG/WebP/GIF 이미지만 업로드할 수 있습니다.');if(file.size>5*1024*1024)throw new Error('이미지는 최대 5MB까지 업로드할 수 있습니다.');const fd=new FormData();fd.append('image',file);const r=await fetch('/api/upload-image',{method:'POST',body:fd});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'이미지 업로드에 실패했습니다.');return d}
async function readBackgroundImage(input){const f=input.files?.[0];if(!f)return;const status=document.getElementById('bgStatus');if(status)status.textContent='업로드 중…';try{const d=await uploadImageFile(f);quiz.theme.background=d.url;quiz.theme.backgroundName=d.name||f.name;drawB()}catch(e){if(status)status.textContent='';alert(e.message||'배경 이미지 업로드에 실패했습니다.')}}
function clearBackground(){quiz.theme.background='';quiz.theme.backgroundName='';drawB()}
function exportQuizJson(){if(!quiz)return;syncBuilderMeta();const out=JSON.stringify(quiz,null,2);const blob=new Blob([out],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=((quiz.title||'quiz-live').replace(/[\\/:*?"<>|]/g,'_')||'quiz-live')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importQuizJson(input){const f=input.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const q=JSON.parse(r.result);if(!q||!Array.isArray(q.questions)||!q.questions.length)throw new Error('문제 목록이 없습니다.');q.id='';delete q.ownerToken;q.title=String(q.title||'가져온 퀴즈').slice(0,120);q.theme=q.theme||{background:'',accent:'#795cff',colors:[...COLORS]};normalizeQuizModes(q);q.questions=q.questions.map(x=>({...nq(),...x}));builder(q)}catch(e){alert('JSON 퀴즈를 불러오지 못했습니다. '+e.message)}};r.readAsText(f);input.value=''}
function moveQuestion(i,dir){const j=i+dir;if(j<0||j>=quiz.questions.length)return;[quiz.questions[i],quiz.questions[j]]=[quiz.questions[j],quiz.questions[i]];drawB()}
function duplicateQuestion(i){quiz.questions.splice(i+1,0,JSON.parse(JSON.stringify(quiz.questions[i])));drawB()}
function setQuizMode(m){quiz.mode=m;applyModeRestrictions(quiz);drawB()}
function dragStartQuestion(i,e){dragQuestionIndex=i;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(i));e.currentTarget.classList.add('dragging')}
function dragEndQuestion(e){e.currentTarget.classList.remove('dragging');dragQuestionIndex=null}
function dragOverQuestion(i,e){e.preventDefault();e.dataTransfer.dropEffect='move'}
function dropQuestion(i,e){e.preventDefault();const from=dragQuestionIndex!==null?dragQuestionIndex:Number(e.dataTransfer.getData('text/plain'));if(!Number.isInteger(from)||from===i||from<0||from>=quiz.questions.length)return;const item=quiz.questions.splice(from,1)[0];quiz.questions.splice(i,0,item);dragQuestionIndex=null;drawB()}
function drawB(){syncBuilderMeta();normalizeQuizModes(quiz);app.innerHTML=`<div class="wrap"><div class="top"><h1>퀴즈 만들기 <small class="version-badge">v7.8</small></h1><div><span class="json-action"><button class="secondary" onclick="exportQuizJson()">⬇ JSON 내보내기</button>${modeHelpMarkup('JSON 내보내기','현재 만든 퀴즈를 .json 파일로 컴퓨터에 저장합니다. 다른 브라우저나 다른 사람에게 퀴즈 설정을 옮길 때 사용할 수 있습니다.')}</span> <span class="json-action"><label class="secondary file-btn">⬆ JSON 불러오기<input type="file" accept="application/json,.json" onchange="importQuizJson(this)" hidden></label>${modeHelpMarkup('JSON 불러오기','이전에 내보낸 QUIZ LIVE .json 파일을 다시 불러와 편집할 수 있습니다. 불러온 내용은 현재 편집 중인 퀴즈로 교체됩니다.')}</span> <button class="secondary" onclick="home()">나가기</button></div></div>
<div class="card"><div class="field"><label>퀴즈 제목</label><input id="title" value="${esc(quiz.title)}" oninput="quiz.title=this.value"></div><div class="field"><label>게임 모드 ${modeHelpMarkup('게임 모드','퀴즈 전체의 진행 방식을 결정합니다. 일반은 함께 진행, 데스 모드는 생존 경쟁, 스피드런은 개인별 즉시 진행, 팀은 RED/BLUE로 균등하게 나눠 진행합니다.')}</label><div class="mode-grid">${['normal','speedrun','team','death'].map(m=>`<button type="button" class="mode-card mode-${m} ${quiz.mode===m?'selected':''}" onclick="setQuizMode('${m}')"><div class="mode-card-copy"><strong>${modeLabel(m)}</strong><small>${esc(modeHelp(m))}</small></div></button>`).join('')}</div></div>${quiz.mode!=='speedrun'?`<div class="field mode-option-row combo-option-card"><div class="option-heading"><div><label>🔥 콤보 시스템 ${modeHelpMarkup('콤보 시스템','정답을 연속으로 맞히면 콤보가 쌓이고 추가 점수를 얻습니다. 오답이나 미응답이면 콤보가 끊깁니다. 2연속부터 추가 보너스가 붙습니다.')}</label><p class="note">${quiz.comboEnabled?'연속 정답 보너스가 적용됩니다.':'기본 점수만 사용합니다.'}</p></div><label class="switch-line"><input type="checkbox" ${quiz.comboEnabled?'checked':''} onchange="quiz.comboEnabled=this.checked"> 사용</label></div></div>`:''}<div class="field"><label>배경 이미지</label><input id="bgFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif" onchange="readBackgroundImage(this)"><p id="bgStatus" class="note">JPG/PNG/WebP/GIF · 최대 5MB · 서버에 안전하게 업로드됩니다.</p>${quiz.theme?.background?`<div class="background-preview"><img src="${esc(quiz.theme.background)}"><div><b>${esc(quiz.theme.backgroundName||'배경 이미지')}</b><button type="button" class="secondary" onclick="clearBackground()">배경 제거</button></div></div>`:''}</div><div class="field"><label>강조색</label><input type="color" value="${quiz.theme.accent}" onchange="quiz.theme.accent=this.value"></div><div class="field"><label>A/B/C/D 기본 색상</label><div class="color-row">${quiz.theme.colors.map((c,i)=>`<div class="color-pick"><span>${String.fromCharCode(65+i)}</span><input type="color" value="${c}" onchange="quiz.theme.colors[${i}]=this.value"></div>`).join('')}</div><p class="note">문제별 색을 따로 지정하지 않으면 이 색상이 사용됩니다.</p></div></div>
<div id="qs"></div><button onclick="quiz.questions.push(nq());drawB()">＋ 문제 추가</button> <button onclick="save()">💾 저장</button> <button class="secondary" onclick="makeRoom()">🚀 바로 방 만들기</button> ${quiz.id?`<button class="danger" onclick="deleteCurrent()">🗑️ 퀴즈 삭제</button>`:``}</div>`;quiz.questions.forEach((q,i)=>drawQ(i,q))}
function drawQ(i,q){const d=document.createElement('div');d.className='card qbox';d.ondragover=e=>dragOverQuestion(i,e);d.ondrop=e=>dropQuestion(i,e);
const colors=(q.colors&&q.colors.length===4)?q.colors:quiz.theme.colors;
d.innerHTML=`<div class="top"><h3><span class="drag-handle" draggable="true" ondragstart="dragStartQuestion(${i},event)" ondragend="dragEndQuestion(event)">☷</span> ${i+1}. 문제</h3><div class="q-tools"><button type="button" class="secondary" onclick="moveQuestion(${i},-1)" ${i===0?'disabled':''}>↑</button><button type="button" class="secondary" onclick="moveQuestion(${i},1)" ${i===((quiz.questions||[]).length-1)?'disabled':''}>↓</button><button type="button" class="secondary" onclick="duplicateQuestion(${i})">복제</button><button class="danger" onclick="quiz.questions.splice(${i},1);if(!quiz.questions.length)quiz.questions.push(nq());drawB()">삭제</button></div></div>
<div class="field"><label>유형</label><select onchange="quiz.questions[${i}].type=this.value;quiz.questions[${i}].answer=this.value==='multiple'?[]:'';drawB()"><option value="choice" ${q.type==='choice'?'selected':''}>${q.raidEnabled?'8지선다':'사지선다'}</option><option value="ox" ${q.type==='ox'?'selected':''}>O/X</option><option value="subjective" ${q.type==='subjective'?'selected':''}>주관식</option><option value="multiple" ${q.type==='multiple'?'selected':''}>복수선택</option><option value="ordering" ${q.type==='ordering'?'selected':''}>순서 맞추기</option></select></div>
<div class="field"><label>문제</label><textarea rows="2" oninput="quiz.questions[${i}].prompt=this.value">${esc(q.prompt)}</textarea></div>
${mediaEditor(i,q)}<div id="in${i}"></div>
<div class="field q-special-options"><label>문제 옵션 <span class="field-help">${modeHelpMarkup('문제 옵션','문제마다 추가 규칙을 켜거나 끌 수 있습니다. 현재 모드에서 지원하지 않는 옵션은 표시되지 않습니다.')}</span></label><div class="special-option-grid">${highRiskAllowed()?`<label class="option-chip option-risk"><input type="checkbox" ${q.highRisk?'checked':''} onchange="toggleHighRisk(${i},this.checked)"><span>⚠️ 하이 리스크</span>${modeHelpMarkup('하이 리스크','문제 시작 전 5초 동안 겁쟁이/도전을 선택합니다. 도전은 정답 2배, 오답은 기본점수만큼 감점됩니다.')}</label>`:''}${raidAllowed()?`<label class="option-chip option-raid"><input type="checkbox" ${q.raidEnabled?'checked':''} onchange="toggleRaid(${i},this.checked)"><span>👑 레이드</span>${modeHelpMarkup('레이드','8지선다 문제입니다. 설정한 정답자 수/비율을 달성하면 성공합니다. 성공 시 빠른 정답자 명단을 보여주고, 실패 시 정답자는 점수를 받지 못하며 오답자는 기본점수만큼 감점됩니다.')}</label>`:''}</div>${q.raidEnabled&&raidAllowed()&&q.type==='choice'?`<div class="raid-config"><select onchange="quiz.questions[${i}].raidThresholdType=this.value;drawB()"><option value="count" ${q.raidThresholdType==='count'?'selected':''}>정답자 N명</option><option value="percent" ${q.raidThresholdType==='percent'?'selected':''}>정답자 N%</option></select><input type="number" min="1" max="100" value="${q.raidThreshold||2}" onchange="quiz.questions[${i}].raidThreshold=+this.value"><span class="note">성공 기준</span></div>`:''}</div><div class="field"><label>제한시간(초)</label><input type="number" min="1" value="${q.timeLimit}" onchange="quiz.questions[${i}].timeLimit=+this.value"></div><div class="field"><label>정답 공개 영상 시간(초)</label><input type="number" min="0" value="${q.revealSeconds}" onchange="quiz.questions[${i}].revealSeconds=+this.value"></div></div>
${mediaSegmentEditor(i,q)}
<label><input type="checkbox" ${q.showVideo?'checked':''} onchange="quiz.questions[${i}].showVideo=this.checked"> 영상 화면 표시</label> <label><input type="checkbox" ${q.revealEnabled?'checked':''} onchange="quiz.questions[${i}].revealEnabled=this.checked"> 정답 공개</label> <label><input type="checkbox" ${q.fever?'checked':''} onchange="quiz.questions[${i}].fever=this.checked;quiz.questions[${i}].platinum=false;drawB()"> 🔥 FEVER ×2</label> <label><input type="checkbox" ${q.platinum?'checked':''} onchange="quiz.questions[${i}].platinum=this.checked;quiz.questions[${i}].fever=false;drawB()"> 💎 PLATINUM ×3</label> <label><input type="checkbox" ${q.allowAnswerChange?'checked':''} onchange="quiz.questions[${i}].allowAnswerChange=this.checked"> 제한시간 동안 답 변경 허용</label> <label><input type="checkbox" ${q.waitFullTime!==false?'checked':''} onchange="quiz.questions[${i}].waitFullTime=this.checked"> 모두 응답해도 제한시간 끝까지 기다리기</label>`;
document.getElementById('qs').appendChild(d);drawIn(i,q,colors)}

function getMediaType(q){if(q.mediaType)return q.mediaType;if(q.audioUrl)return 'audio';if(q.videoId)return 'youtube';if(q.imageUrl)return 'image';return 'none'}
function mediaEditor(i,q){const t=getMediaType(q);return `<div class="field media-field"><label>문제 자료</label><p class="note">문제 하나에 자료 한 종류만 선택하면 됩니다. 사진 문제는 사진만, 음악 문제는 음악만, YouTube 문제는 YouTube만 넣어주세요.</p><div class="media-tabs"><button type="button" class="media-tab ${t==='image'?'active':''}" onclick="setMediaType(${i},'image')">🖼️ 사진</button><button type="button" class="media-tab ${t==='audio'?'active':''}" onclick="setMediaType(${i},'audio')">🎵 음악</button><button type="button" class="media-tab ${t==='youtube'?'active':''}" onclick="setMediaType(${i},'youtube')">▶ YouTube</button></div>${t==='image'?`<div class="media-panel"><input type="file" accept="image/*" onchange="readQuestionImage(${i},this)"><p class="note">JPG/PNG 등 · 5MB 이하 권장</p>${q.imageUrl?`<div class="question-image-preview"><img src="${esc(q.imageUrl)}"><button type="button" class="secondary" onclick="clearMedia(${i})">사진 제거</button></div>`:''}</div>`:t==='audio'?`<div class="media-panel"><input type="file" accept="audio/*,.mp3,.wav,.m4a,.ogg" onchange="readQuestionAudio(${i},this)"><p class="note">MP3/WAV/M4A/OGG · 파일당 최대 20MB · 업로드 후 서버 파일로 저장됩니다.</p><p class="note upload-status"></p>${q.audioUrl?`<div class="audio-file-row"><b>${esc(q.audioName||'업로드 음악')}</b><button type="button" class="secondary" onclick="clearMedia(${i})">음악 제거</button></div>`:''}</div>`:t==='youtube'?`<div class="media-panel"><input id="vid${i}" placeholder="YouTube 링크 또는 영상 ID" value="${esc(q.videoId)}" oninput="quiz.questions[${i}].videoId=parseVideo(this.value)"><p class="note">YouTube 영상의 문제 구간을 지정해 사용할 수 있어요.</p></div>`:`<div class="media-panel muted">자료 없이 텍스트만으로 문제를 만들어요.</div>`}</div>`}
function setMediaType(i,t){const q=quiz.questions[i];q.mediaType=t;if(t!=='image')q.imageUrl='';if(t!=='audio'){q.audioUrl='';q.audioName=''}if(t!=='youtube')q.videoId='';drawB()}
function clearMedia(i){const q=quiz.questions[i];q.mediaType='';q.imageUrl='';q.audioUrl='';q.audioName='';q.videoId='';drawB()}
function mediaSegmentEditor(i,q){const t=getMediaType(q);if(t!=='youtube'&&t!=='audio')return '';return `<div class="grid"><div class="field"><label>시작구간(초)</label><input id="st${i}" type="number" min="0" step="0.1" value="${q.start}" onchange="quiz.questions[${i}].start=+this.value"></div><div class="field"><label>종료구간(초)</label><input id="en${i}" type="number" min="0.1" step="0.1" value="${q.end}" onchange="quiz.questions[${i}].end=+this.value"></div></div>${t==='youtube'?`<div class="preview-actions"><button class="secondary" onclick="preview(${i})">▶ 구간 미리듣기</button><span class="muted">입력한 시작~종료 구간을 바로 확인할 수 있어요.</span></div><div id="pv${i}" class="preview-box"></div>`:''}`}

function drawIn(i,q,colors){const e=document.getElementById('in'+i);if(q.type==='choice'||q.type==='multiple')e.innerHTML=(q.options||['','','','']).map((o,j)=>`<div class="option-edit"><input value="${esc(o)}" placeholder="선택지 ${j+1}" oninput="quiz.questions[${i}].options[${j}]=this.value"><div class="option-tools"><label><input type="${q.type==='multiple'?'checkbox':'radio'}" name="a${i}" ${q.type==='choice'&&q.answer===o?'checked':''} ${q.type==='multiple'&&Array.isArray(q.answer)&&q.answer.includes(o)?'checked':''} onchange="setAnswer(${i},${j},this)"> 정답</label><label class="swatch-label">색 <input type="color" value="${colors[j]||COLORS[j]}" onchange="setQColor(${i},${j},this.value)"></label></div></div>`).join('')+(q.type==='choice'&&!q.raidEnabled&&((q.options||[]).length<8)?`<button type="button" class="secondary" onclick="quiz.questions[${i}].options.push('');drawB()">＋ 선택지 추가</button>`:'')+(q.type==='choice'&&q.raidEnabled?`<p class="note">👑 레이드는 8지선다 고정입니다.</p>`:'');else if(q.type==='ox'){const a=String(q.answer||'').toUpperCase();e.innerHTML=`<div class="ox-key-editor"><button type="button" class="ox-key ${a==='O'?'selected':''}" onclick="quiz.questions[${i}].answer='O';drawB()">⭕ O</button><button type="button" class="ox-key ${a==='X'?'selected':''}" onclick="quiz.questions[${i}].answer='X';drawB()">❌ X</button></div><p class="muted">정답으로 선택된 버튼이 강조됩니다. 현재 정답: <b>${esc(a||'미설정')}</b></p>`}else if(q.type==='subjective'){const answers=Array.isArray(q.answer)?q.answer:[q.answer].filter(Boolean);const slots=Math.max(2,answers.length);e.innerHTML=`<div class="subjective-key-editor"><p class="note">아래 칸 중 하나와 일치하면 정답 처리됩니다. 같은 문제에서 인정할 정답을 각각 입력하세요.</p>${Array.from({length:slots},(_,j)=>`<div class="answer-slot"><span>정답 ${j+1}</span><input value="${esc(answers[j]||'')}" placeholder="인정할 정답 ${j+1}" oninput="setSubjectiveAnswer(${i},${j},this.value)"></div>`).join('')}<button type="button" class="secondary" onclick="addSubjectiveAnswer(${i})">＋ 정답 칸 추가</button></div>`}else{const opts=q.options||['','','',''];const answer=Array.isArray(q.answer)?q.answer:[];e.innerHTML=`<div class="ordering-editor"><p class="note">정답 순서를 칸마다 하나씩 선택하세요. 예: 2 → 1 → 4 → 3</p><div class="ordering-slots">${opts.map((_,j)=>`<label class="order-slot"><span>${j+1}번째</span><select onchange="setOrderingAnswer(${i},${j},this.value)"><option value="">선택</option>${opts.map((o,k)=>`<option value="${k+1}" ${Number(answer[j])===k+1?'selected':''}>${k+1}. ${esc(o||'항목 '+(k+1))}</option>`).join('')}</select></label>`).join('')}</div></div>`}}
async function readQuestionImage(i,input){const f=input.files?.[0];if(!f)return;try{const d=await uploadImageFile(f);quiz.questions[i].imageUrl=d.url;quiz.questions[i].imageName=d.name||f.name;drawB()}catch(e){alert(e.message||'사진 업로드에 실패했습니다.')}}
async function readQuestionAudio(i,input){const f=input.files?.[0];if(!f)return;if(f.size>20*1024*1024)return alert('음악 파일은 최대 20MB까지 선택할 수 있습니다.');if(!f.type.startsWith('audio/'))return alert('MP3, WAV 등 오디오 파일만 선택해주세요.');const q=quiz.questions[i],btn=input;btn.disabled=true;const oldText=input.parentElement?.querySelector('.upload-status');if(oldText)oldText.textContent='음악 업로드 중…';try{const fd=new FormData();fd.append('audio',f);const r=await fetch('/api/upload-audio',{method:'POST',body:fd});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'음악 업로드에 실패했습니다.');q.audioUrl=d.url;q.audioName=d.name||f.name;q.mediaType='audio';drawB()}catch(e){alert(e.message||'음악 업로드에 실패했습니다.')}finally{btn.disabled=false}}
function setQColor(i,j,v){const q=quiz.questions[i];q.colors=q.colors&&q.colors.length===4?[...q.colors]:[...quiz.theme.colors];q.colors[j]=v}
function setAnswer(i,j,el){const q=quiz.questions[i],v=q.options[j];if(q.type==='choice')q.answer=v;else{q.answer=[...(q.answer||[])];if(el.checked){if(!q.answer.includes(v))q.answer.push(v)}else q.answer=q.answer.filter(x=>x!==v)}}
function setSubjectiveAnswer(i,j,v){const q=quiz.questions[i];const a=Array.isArray(q.answer)?[...q.answer]:[];while(a.length<=j)a.push('');a[j]=v.trim();q.answer=a.filter(Boolean)}
function addSubjectiveAnswer(i){const q=quiz.questions[i];const a=Array.isArray(q.answer)?[...q.answer]:[];a.push('');q.answer=a;drawB()}
function setOrderingAnswer(i,j,v){const q=quiz.questions[i];const a=Array.isArray(q.answer)?[...q.answer]:[];while(a.length<=j)a.push('');a[j]=v?Number(v):'';q.answer=a}
function parseVideo(v){try{let u=new URL(v);return u.hostname.includes('youtu.be')?u.pathname.slice(1).split('/')[0]:u.searchParams.get('v')||v.trim()}catch{return v.trim()}}
function vid(v){return parseVideo(v).match(/^[A-Za-z0-9_-]{6,}$/)?.[0]||''}
function ytFrame(v,start,end,controls=true,participant=false){const id=vid(v);if(!id)return '';const s=Math.max(0,Number(start)||0),e=Math.max(0,Number(end)||0);const p=`autoplay=1&mute=0&controls=${controls?1:0}&disablekb=1&fs=0&rel=0&modestbranding=1&playsinline=1&iv_load_policy=3&cc_load_policy=0&enablejsapi=1&origin=${encodeURIComponent(location.origin)}&start=${Math.floor(s)}${e>s?`&end=${Math.floor(e)}`:''}`;return `<div class="yt-crop ${participant?'participant-yt':''}"><iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?${p}" allow="autoplay; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin"></iframe></div>`}
function preview(i){const q=quiz.questions[i],id=vid(q.videoId);if(!id)return alert('YouTube 링크를 입력해주세요.');if(!(Number(q.end)>Number(q.start)))return alert('종료 시간이 시작 시간보다 커야 합니다.');document.getElementById('pv'+i).innerHTML=`<div class="preview-head"><b>구간 미리듣기</b><span>${q.start}초 → ${q.end}초</span><button class="secondary" onclick="document.getElementById('pv${i}').innerHTML=''">닫기</button></div><div class="video preview-video">${ytFrame(id,q.start,q.end,true)}</div>`}
async function save({silent=false}={}){syncBuilderMeta();normalizeQuizModes(quiz);quiz.title=document.getElementById('title').value.trim()||'무제 퀴즈';if((quiz.questions||[]).some(q=>String(q.audioUrl||'').startsWith('data:audio/')))return alert('음악 파일이 아직 이전 방식으로 저장되어 있습니다. 음악을 다시 선택해 서버에 업로드한 뒤 저장해주세요.');quiz.theme.background=quiz.theme.background||'';for(const q of quiz.questions){if(q.raidEnabled&&quiz.mode!=='speedrun'&&quiz.mode!=='team'&&(q.type!=='choice'||(q.options||[]).length!==8))return alert('레이드 문제는 복수선택이 아닌 8지선다 문제여야 합니다.');if(q.videoId&&!(Number(q.end)>Number(q.start)))return alert('YouTube 문제는 시작/종료구간을 확인해주세요.');if((q.type==='choice'||q.type==='multiple')&&(q.options||[]).some(x=>!String(x).trim()))return alert('선택지를 모두 입력해주세요.');}const isEdit=!!quiz.id,headers={'Content-Type':'application/json'};let token=isEdit?localStorage.getItem('owner-'+quiz.id):null;if(isEdit){if(!token)return alert('관리 링크가 없어서 수정 권한을 확인할 수 없습니다.');headers['x-owner-token']=token}let r,d;try{r=await fetch(isEdit?'/api/quizzes/'+quiz.id:'/api/quizzes',{method:isEdit?'PUT':'POST',headers,body:JSON.stringify(quiz)});d=await r.json()}catch(e){return alert('저장 중 서버 오류가 발생했습니다. Render 로그를 확인해주세요.')}if(!r.ok){if(!silent)alert(d.error||'저장에 실패했습니다.');return false}if(!isEdit){quiz.id=d.id;token=d.ownerToken;localStorage.setItem('owner-'+d.id,token)}saveLocalQuiz(quiz,token);if(!silent)showSaved(token);return true}
function showSaved(token){const participant=`${location.origin}/?quiz=${quiz.id}`,manage=`${location.origin}/?manage=${quiz.id}&token=${encodeURIComponent(token)}`;app.innerHTML=`<div class="wrap"><div class="hero"><div class="logo">🎉 저장 완료</div><p>참가 링크와 비밀 관리 링크를 보관하세요.</p></div><div class="card"><h3>🎮 참가 링크</h3><div class="link-row"><input value="${participant}" readonly><button onclick="copyText('${participant}')">복사</button></div></div><div class="card manage-card"><h3>🔐 비밀 관리 링크</h3><p class="note">이 링크가 있으면 로그인 없이 퀴즈를 수정하거나 삭제할 수 있습니다. 다른 사람에게 공개하지 마세요.</p><div class="link-row"><input value="${manage}" readonly><button onclick="copyText('${manage}')">복사</button></div></div><button onclick="createRoomById(quiz.id)">방 만들기</button> <button class="secondary" onclick="builder(quiz)">퀴즈 수정</button></div>`}
async function copyText(t){try{await navigator.clipboard.writeText(t);alert('복사 완료')}catch{prompt('아래 링크를 복사하세요.',t)}}
async function makeRoom(){if(!quiz)return alert('퀴즈를 먼저 만들어주세요.');syncBuilderMeta();const ok=await save({silent:true});if(!ok)return;return createRoomById(quiz.id)}
async function makeRoomForQuiz(id){return createRoomById(id)}
async function createRoomById(id){if(!id)return alert('퀴즈 정보를 찾을 수 없습니다.');try{const r=await fetch('/api/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({quizId:id})});const d=await r.json().catch(()=>({}));if(!r.ok)return alert(d.error||'방을 만들 수 없습니다.');if(!d.code)return alert('방 코드 생성에 실패했습니다.');code=String(d.code);role='host';const joinHost=()=>socket.emit('host:join',{code});if(socket.connected)joinHost();else socket.once('connect',joinHost)}catch(e){console.error(e);alert('방 생성 중 서버 오류가 발생했습니다.')}}
function join(){primeAudio();code=document.getElementById('jc').value.trim();const nickname=document.getElementById('jn').value.trim();if(!/^\d{6}$/.test(code))return alert('방 코드를 6자리 숫자로 입력해주세요.');if(!nickname)return alert('닉네임을 입력해주세요.');role='player';playerAvatar=sessionStorage.getItem('quiz-live-avatar')||'🦊';sessionStorage.setItem('quiz-live-room',code);sessionStorage.setItem('quiz-live-nickname',nickname);sessionStorage.setItem('quiz-live-avatar',playerAvatar);socket.emit('player:join',{code,nickname,avatar:playerAvatar,reconnectToken:sessionStorage.getItem('quiz-live-reconnect')||''})}
function joinPage(prefill=''){app.innerHTML=`<div class="wrap join-screen"><div class="hero"><div class="logo">🎮 참가하기</div><p class="muted">닉네임과 아바타를 정하고 게임에 참가하세요.</p></div><div class="card join-card"><div class="field"><label>방 코드</label><input id="jc" value="${esc(prefill)}" maxlength="6" placeholder="방 코드" inputmode="numeric"></div><div class="field"><label>닉네임</label><input id="jn" maxlength="20" placeholder="닉네임"></div>${avatarPicker()}<button onclick="join()">참가하기</button></div></div>`}
function roomLink(){return `${location.origin}/?room=${encodeURIComponent(code)}`}
function lobby(s){const m=s?.mode||'normal',link=roomLink();app.innerHTML=`<div class="wrap room-lobby"><section class="mode-hero mode-${esc(m)}"><div class="mode-kicker">QUIZ LIVE · GAME MODE</div><div class="mode-emblem">${m==='death'?'☠️':m==='speedrun'?'⚡':m==='team'?'🔴🔵':'🎯'}</div><div class="mode-title">${esc(m==='death'?'데스 모드':m==='speedrun'?'스피드런':m==='team'?'팀 모드':'일반 모드')}</div><p>${esc(modeHelp(m))}</p>${m==='team'?'<span class="mode-lobby-note">참가자는 RED / BLUE로 자동 균등 배정됩니다.</span>':''}${s?.comboEnabled?'<span class="mode-lobby-note">🔥 콤보 시스템 ON</span>':''}</section><div class="card lobby-join-card"><div class="big">${code}</div><p class="muted" style="text-align:center">친구에게 방 코드 또는 QR을 보내주세요.</p><div class="lobby-qr"><img src="/api/room/${encodeURIComponent(code)}/qr" alt="방 입장 QR"></div><div class="link-row"><input value="${esc(link)}" readonly><button onclick="copyText('${link}')">링크 복사</button></div></div><div class="card"><h2>참가자 <span id="cnt">0</span>/32</h2><div id="people"></div>${role==='host'?'<button onclick="primeAudio();socket.emit(\'host:start\')">🚀 시작</button>':'<button class="secondary" onclick="primeAudio();alert(\'게임 소리를 미리 활성화했습니다.\')">🔊 게임 소리 활성화</button><p class="muted">주최자를 기다리는 중…</p>'}</div></div>`;update(s)}
function update(s){window.__roomState=s;window.__roomQuizTheme=s.theme||{};applyTheme(window.__roomQuizTheme);if(s.mode==='speedrun'){const sp=document.querySelector('.speedrun-live-panel');if(sp){const n=document.createElement('div');n.innerHTML=speedrunPlayers();sp.replaceWith(n.firstElementChild)}}if(s.mode==='team'){const tp=document.querySelector('.team-panel');if(tp){const n=document.createElement('div');n.innerHTML=renderTeamPanel();tp.replaceWith(n.firstElementChild)}}if(s.mode==='death'){const dp=document.querySelector('.death-panel');if(dp){const n=document.createElement('div');n.innerHTML=renderDeathPanel();dp.replaceWith(n.firstElementChild)}}let c=document.getElementById('cnt'),p=document.getElementById('people');if(c)c.textContent=s.participants.length;if(p)p.innerHTML=s.participants.map(x=>`<div class="top lobby-person"><span class="lobby-player-name">${avatarMarkup(x.avatar||'🦊','lobby-avatar')} ${esc(x.nickname)} ${s.mode==='team'?`<small>${x.team==='red'?'🔴':'🔵'}</small>`:''}</span><span>${role==='host'?x.score+'점 ':''}${x.answered?'✓':''}</span></div>`).join('');const me=s.participants.find(x=>x.id===socket.id||x.nickname===sessionStorage.getItem('quiz-live-nickname'));const scoreEl=document.getElementById('myScore');if(scoreEl&&me)scoreEl.textContent=me.score+'점';const rankEl=document.getElementById('myRank'),chaserEl=document.getElementById('myChaser');if(rankEl&&me){const comboEl=document.getElementById('myCombo');if(comboEl)comboEl.textContent=me.combo||0;const comboWrap=document.getElementById('myComboWrap');if(comboWrap)comboWrap.classList.toggle('active',!!me.combo);const sorted=[...s.participants].sort((a,b)=>b.score-a.score||a.nickname.localeCompare(b.nickname));const idx=sorted.findIndex(x=>x.id===me.id);rankEl.textContent=(idx+1)+'위';if(chaserEl){const chaser=sorted[idx+1];chaserEl.textContent=chaser?`${chaser.nickname}님이 추격 중`:'뒤에서 추격 중인 참가자 없음';chaserEl.classList.toggle('has-chaser',!!chaser);}}const av=document.getElementById('myAvatar');if(av&&me)av.innerHTML=avatarMarkup(me.avatar||'🦊','player-avatar-img');const ac=document.getElementById('hostAnswered');if(ac)ac.textContent=`${s.answeredCount||0}/${s.participants.length}`;(s.answerCounts||[]).forEach((n,i)=>{const el=document.getElementById('hc'+i);if(el)el.textContent=n})}
function audioTag(q){if(!q.audioUrl)return '';return `<div class="audio-wrap"><audio id="qAudio" src="${q.audioUrl}" preload="auto" playsinline></audio><div class="eq">${'<i></i>'.repeat(9)}</div></div>`}
function mediaVolumeKey(q){return q?.audioUrl?'quiz-live-music-volume':'quiz-live-youtube-volume'}
function getMediaVolume(q){const fallback=q?.audioUrl?70:60;const n=Number(localStorage.getItem(mediaVolumeKey(q)));return Number.isFinite(n)?Math.max(0,Math.min(100,n)):fallback}
function playerVolumeControl(q){if(!q?.audioUrl&&!q?.videoId)return '';const kind=q.audioUrl?'음악':'YouTube';const v=getMediaVolume(q);return `<div class="player-volume"><div class="player-volume-head"><span>🔊 ${kind} 음량</span><strong id="mediaVolumeValue">${v}%</strong></div><input id="mediaVolume" type="range" min="0" max="100" step="1" value="${v}" aria-label="${kind} 음량" oninput="setMediaVolume(this.value)"></div>`}
function postYoutubeVolume(v){const payload=JSON.stringify({event:'command',func:'setVolume',args:[Math.max(0,Math.min(100,Number(v)||0))]});document.querySelectorAll('iframe').forEach(f=>{try{f.contentWindow.postMessage(payload,'*')}catch{}})}
function setMediaVolume(value){const q=window.__currentQ;if(!q)return;const v=Math.max(0,Math.min(100,Number(value)||0));localStorage.setItem(mediaVolumeKey(q),String(v));const out=document.getElementById('mediaVolumeValue');if(out)out.textContent=v+'%';const a=document.getElementById('qAudio');if(a)a.volume=v/100;if(q.videoId)postYoutubeVolume(v)}
function media(q,reveal=false,participant=false){const photo=q.imageUrl?`<div class=\"question-image\"><img src=\"${esc(q.imageUrl)}\"></div>`:'';if(q.audioUrl)return photo+audioTag(q);if(!q.videoId)return photo||`<div class=\"eq\">${'<i></i>'.repeat(7)}</div>`;const id=vid(q.videoId);if(!id)return photo;if(!q.showVideo&&!reveal)return photo+`<div class=\"card audio-hidden\"><div class=\"eq\">${'<i></i>'.repeat(9)}</div><p style=\"text-align:center\">🎵 AUDIO PLAYING</p><iframe class=\"hidden-audio-frame\" src=\"https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?autoplay=1&mute=0&controls=0&disablekb=1&rel=0&playsinline=1&cc_load_policy=0&enablejsapi=1&origin=${encodeURIComponent(location.origin)}&start=${Math.floor(q.start||0)}&end=${Math.floor(q.end||0)}\" allow=\"autoplay; encrypted-media\"></iframe></div>`;return photo+ytFrame(id,q.start,q.end,false,participant)}
function renderDeathPanel(){const s=window.__roomState;if(!s||s.mode!=='death')return '';const ps=[...(s.participants||[])];return `<aside class="death-panel"><div class="death-panel-head"><div><b>☠️ SURVIVORS</b><small>${ps.filter(x=>!x.eliminated).length}명 생존</small></div><strong>${ps.length}</strong></div><div class="death-grid">${ps.map(x=>`<div class="death-player ${x.eliminated?'dead':''}">${avatarMarkup(x.avatar||'🦊','death-avatar')}<span>${esc(x.nickname)}</span>${x.eliminated?'<i>OUT</i>':''}</div>`).join('')}</div></aside>`}function renderTeamPanel(){const s=window.__roomState;if(!s||s.mode!=='team')return '';const me=s.participants.find(x=>x.id===socket.id)||s.participants.find(x=>x.nickname===sessionStorage.getItem('quiz-live-nickname'));const team=me?.team||'red';const members=s.participants.filter(x=>x.team===team);const acc=members[0]?.teamAccuracy??0;return `<aside class="team-panel"><div class="team-panel-title">${team==='red'?'🔴 RED TEAM':'🔵 BLUE TEAM'} <b>${acc}%</b></div>${members.map(x=>`<div class="team-member">${avatarMarkup(x.avatar||'🦊','team-member-avatar')}<span>${esc(x.nickname)}</span><small>${x.teamAccuracy??0}%</small></div>`).join('')}</aside>`}function showRiskChoice(d){clearInterval(timer);const q=d.question,deadline=Number(d.deadline)||Date.now()+5000;app.innerHTML=`<div class="wrap risk-choice-screen high-risk-active"><div class="risk-fire-aura" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="hero"><div class="logo high-risk-logo">⚠️ HIGH RISK</div><div class="risk-warning">RISK / REWARD</div><h1>${esc(q.prompt)}</h1><p class="muted">5초 안에 선택하세요. 선택하지 않으면 겁쟁이로 처리됩니다.</p></div><div class="risk-choice-grid"><button id="riskCoward" onclick="chooseRisk('coward')" class="risk-card coward"><strong>겁쟁이</strong><span>정상 점수</span></button><button id="riskChallenge" onclick="chooseRisk('challenge')" class="risk-card challenge"><strong>도전</strong><span>정답 2배 · 오답 기본점수만큼 마이너스</span></button></div><div id="riskTimer" class="risk-countdown">5</div><p id="riskChoiceStatus" class="risk-choice-status">선택 후에도 5초가 끝날 때까지 다시 바꿀 수 있습니다.</p></div>`;const tick=()=>{const el=document.getElementById('riskTimer');if(!el)return;const sec=Math.max(0,Math.ceil((deadline-Date.now())/1000));el.textContent=sec;if(sec<=0){clearInterval(timer);return}};tick();timer=setInterval(tick,100)}function chooseRisk(choice){const selected=document.getElementById(choice==='challenge'?'riskChallenge':'riskCoward');document.querySelectorAll('.risk-card').forEach(b=>{b.classList.remove('selected')});if(selected)selected.classList.add('selected');const st=document.getElementById('riskChoiceStatus');if(st)st.textContent=choice==='challenge'?'도전 선택 · 5초가 끝날 때까지 다시 바꿀 수 있습니다.':'겁쟁이 선택 · 5초가 끝날 때까지 다시 바꿀 수 있습니다.';socket.timeout(1500).emit('question:riskChoice',{choice},()=>{})}
function specialCountdownScreen(kind,d){
 clearInterval(timer);
 const q=d.question||{};
 const isRaid=kind==='raid';
 const sec0=Math.max(1,Number(d.seconds)||(isRaid?7:5));
 let sec=sec0;
 if(isRaid){
   const threshold=q.raidThresholdType==='percent'
     ? `생존 참가자의 ${Math.max(1,Math.min(100,Number(q.raidThreshold)||1))}% 이상 정답`
     : `정답자 ${Math.max(1,Number(q.raidThreshold)||1)}명 이상`;
   app.innerHTML=`<div class="wrap raid-intro-screen">
     <div class="hero raid-intro-hero">
       <div class="raid-intro-art" aria-hidden="true">
         <div class="raid-reaper">☠️</div>
         <div class="raid-chain chain-a">⛓</div><div class="raid-chain chain-b">⛓</div>
         <div class="raid-chain chain-c">⛓</div><div class="raid-chain chain-d">⛓</div>
       </div>
       <div class="mode-mini-badge">👑 RAID INCOMING</div>
       <div class="raid-intro-rules">
         <div class="raid-rule-title">RAID RULES</div>
         <div class="raid-rule-main">이 문제는 8지선다 레이드입니다.</div>
         <div class="raid-rule-detail">${esc(threshold)}이면 <b>레이드 성공</b></div>
         <div class="raid-rule-detail">성공: 정답자 점수 지급 · 실패: 정답자 점수 없음</div>
         <div class="raid-rule-note">지금은 규칙 확인 시간입니다. 카운트가 끝나면 바로 문제를 시작합니다.</div>
       </div>
       <div class="big intro-count" id="introTimer">${sec}</div>
       <div class="raid-next-label">${Number(d.index||0)+1}번 문제 준비</div>
     </div>
   </div>`;
   playRaidDoomSound();
 }else{
   app.innerHTML=`<div class="wrap risk-intro-screen high-risk-active">
     <div class="risk-fire-aura" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div>
     <div class="hero risk-intro-hero">
       <div class="high-risk-logo logo">⚠️ HIGH RISK</div>
       <div class="risk-warning">RISK / REWARD</div>
       <div class="risk-intro-art-static" aria-hidden="true">⚠️</div>
       <div class="risk-host-rules"><b>문제 시작 전 5초 선택</b><span>겁쟁이: 정상 점수 · 도전: 정답 2배 / 오답 기본점수만큼 감점</span><small>5초 동안 선택을 자유롭게 바꿀 수 있습니다.</small></div>
       <div class="big intro-count risk-countdown" id="introTimer">${sec}</div>
       <div class="risk-next-label">${Number(d.index||0)+1}번 문제 준비</div>
     </div>
   </div>`;
 }
 const tick=()=>{const el=document.getElementById('introTimer');if(!el)return;const left=Math.max(0,Number(d.deadline||Date.now()+sec0*1000)-Date.now());const shown=Math.ceil(left/1000);el.textContent=shown;if(shown<=0)clearInterval(timer)};
 tick();
 timer=setInterval(tick,100);
}
function riskHostView(d){specialCountdownScreen('risk',d)}
function raidIntroView(d){specialCountdownScreen('raid',d)}
function speedrunHostView(d){clearInterval(timer);applyTheme(window.__roomQuizTheme||{});app.innerHTML=`<div class="wrap speedrun-host-screen"><div class="speedrun-layout"><main><div class="mode-hero mode-speedrun"><div class="mode-emblem">⚡</div><div class="mode-title">스피드런 관전</div><p>답을 제출하는 즉시 다음 문제로 이동합니다. 정확하고 빠르게 푸는 사람이 승리합니다.</p><span class="mode-lobby-note">출제자의 관전 화면입니다.</span></div><div class="card"><b>참가자의 문제 풀이와 진행 상황을 실시간으로 관전할 수 있습니다.</b></div></main>${speedrunPlayers()}</div></div>`;update(window.__roomState||{participants:[],mode:'speedrun',totalQuestions:d.total||0})}

function speedrunHostQuestion(d){
 if(role!=='host')return;
 clearInterval(timer);window.__currentQ=d.question;
 const q=d.question;
 const main=document.querySelector('.speedrun-host-screen main');
 if(!main)return;
 main.innerHTML=`<div class="mode-hero mode-speedrun speedrun-watch-hero"><div class="mode-emblem">⚡</div><div class="mode-title">스피드런 관전</div><p>Q ${d.index+1} / ${d.total}</p><div class="speedrun-watch-question"><h2>${esc(q.prompt)}</h2>${media(q,false,false)}${playerVolumeControl(q)}</div><button class="secondary" onclick="unlockAudio()">🔊 소리 켜기</button></div>`;
 if(q.audioUrl)startAudioSegment(q);
 if(q.videoId){setTimeout(()=>{postYoutubeVolume(getMediaVolume(q));postYoutubeUnmute();postYoutubePlay()},120);setTimeout(()=>{postYoutubeUnmute();postYoutubePlay()},500)}
}
function speedrunPlayers(){const s=window.__roomState;if(!s)return '';const ps=[...(s.participants||[])].sort((a,b)=>(b.score-a.score)||(b.speedIndex-a.speedIndex)||(a.speedElapsed-b.speedElapsed));return `<aside class="speedrun-live-panel"><div class="speedrun-players-title">⚡ LIVE RANKING <span>실시간</span></div>${ps.map((x,ri)=>`<div class="speedrun-player ${x.speedFinished?'goal':''}"><b class="speedrun-rank">${ri+1}</b>${avatarMarkup(x.avatar||'🦊','speedrun-avatar')}<span><b>${esc(x.nickname)}</b><small>${x.speedFinished?'GOAL':`Q${Math.min(x.speedIndex+1,s.totalQuestions)}/${s.totalQuestions}`}</small></span><small class="speed-elapsed">${(Math.max(0,x.speedElapsed||0)/1000).toFixed(1)}s</small><b class="speed-score">${x.score}점</b></div>`).join('')}</aside>`}
function speedrunQuestion(d){clearInterval(timer);currentQuestionIndex=d.index;window.__currentQ=d.question;currentQuestionOptions=d.question.options||[];locked=false;const q=d.question;const end=Date.now()+q.timeLimit*1000;app.innerHTML=`<div class="wrap game-screen speedrun-screen"><div class="speedrun-layout"><main><div class="player-topbar"><div class="player-identity"><div class="player-avatar">${avatarMarkup(playerAvatar,'player-avatar-img')}</div><div><b>${esc(sessionStorage.getItem('quiz-live-nickname')||'Player')}</b><small id="myRank">RUN</small></div></div><div class="game-stats"><span>SCORE <strong id="myScore">${d.score||0}점</strong></span><span>Q <strong>${d.index+1}<small>/${d.total}</small></strong></span><span class="timer"><small>남은 시간</small><strong id="tm">${q.timeLimit}</strong><em>초</em></span></div></div><div class="game-question-card"><div class="question-meta"><span>⚡ SPEEDRUN</span><button class="sound-btn secondary" onclick="unlockAudio()">🔊 소리 켜기</button></div><h1>${esc(q.prompt)}</h1>${media(q,false,true)}${playerVolumeControl(q)}</div><div id="ans" class="answers game-answers">${buttons(q)}</div></main>${speedrunPlayers()}</div></div>`;timer=setInterval(()=>{const x=Math.max(0,(end-Date.now())/1000),e=document.getElementById('tm');const sec=Math.ceil(x);if(e)e.textContent=sec;if(x<=0){clearInterval(timer);socket.emit('speedrun:timeout',{index:d.index})}},100)}
function question(d){if(role==='host')return hostQuestion(d);applyTheme(window.__roomQuizTheme||{});const q=d.question;currentQuestionIndex=d.index;window.__playerEliminated=!!window.__roomState?.participants?.find(x=>x.id===socket.id)?.eliminated;lastPlayerResult=null;revealPending=null;window.__currentQ=q;window.__submittedSubjective='';currentQuestionOptions=q.options||[];allowAnswerChange=!!q.allowAnswerChange;const end=Date.now()+q.timeLimit*1000;locked=false;window.__lastTimerSecond=q.timeLimit;const raidBattle=!!q.raidEnabled;const raidFx=raidBattle?`<div class="raid-battle-fx" aria-hidden="true"><div class="raid-boss-seal">👑<span>RAID</span></div><div class="raid-battle-chain rb1">⛓️⛓️⛓️</div><div class="raid-battle-chain rb2">⛓️⛓️⛓️</div><div class="raid-battle-chain rb3">⛓️⛓️</div><div class="raid-battle-chain rb4">⛓️⛓️</div><div class="raid-battle-chain rb5">⛓️⛓️⛓️</div><div class="raid-battle-chain rb6">⛓️⛓️⛓️</div><div class="raid-battle-vignette"></div></div>`:'';app.innerHTML=`<div class="wrap game-screen ${raidBattle?'raid-battle-screen':''}">${raidFx}<div class="game-layout"><main><div class="player-topbar"><div class="player-identity"><div id="myAvatar" class="player-avatar">${avatarMarkup(playerAvatar,'player-avatar-img')}</div><div class="player-rank-info"><div><b>${esc(sessionStorage.getItem('quiz-live-nickname')||'Player')}</b><small id="myRank">-위</small></div><span id="myChaser" class="my-chaser"></span></div></div><div class="game-stats"><span> SCORE <strong id="myScore">${(window.__roomState?.participants?.find(x=>x.id===socket.id)?.score)||0}점</strong></span><span id="myComboWrap" class="combo-hud">COMBO <strong id="myCombo">${(window.__roomState?.participants?.find(x=>x.id===socket.id)?.combo)||0}</strong></span><span> Q <strong class="question-progress">${d.index+1}<small>/${d.total}</small></strong></span><span class="timer"><small>남은 시간</small><strong id="tm">${q.timeLimit}</strong><em>초</em></span></div></div><div class="game-question-card ${q.fever?'fever':q.platinum?'platinum':''}"><div class="question-meta"><span>${q.fever?'🔥 FEVER ×2':q.platinum?'💎 PLATINUM ×3':'QUESTION'}</span><button class="sound-btn secondary" onclick="unlockAudio()">🔊 소리 켜기</button></div><h1>${esc(q.prompt)}</h1>${media(q,false,true)}${playerVolumeControl(q)}</div><div id="ans" class="answers game-answers">${window.__playerEliminated?`<div class="death-spectator-answer"><div class="death-spectator-icon">☠️</div><strong>탈락 · 관전 중</strong><span>이제 답안에는 참여할 수 없지만 문제의 영상과 정답 공개는 계속 볼 수 있습니다.</span></div>`:buttons(q)}</div></main>${renderTeamPanel()}${renderDeathPanel()}</div></div>`;clearInterval(timer);timer=setInterval(()=>{let x=Math.max(0,(end-Date.now())/1000),e=document.getElementById('tm');const sec=Math.ceil(x);if(e){e.textContent=sec;e.classList.toggle('urgent',sec<=5&&sec>0);e.classList.toggle('danger',sec<=3&&sec>0)}if(sec!==window.__lastTimerSecond&&sec<=5&&sec>0){window.__lastTimerSecond=sec}if(x<=0){clearInterval(timer);socket.emit('question:timeoutCheck',{index:currentQuestionIndex})}},100);if(q.videoId){const kick=()=>{postYoutubeVolume(getMediaVolume(q));postYoutubeUnmute();postYoutubePlay()};document.querySelectorAll('.game-question-card iframe').forEach(f=>{f.addEventListener('load',()=>{kick();setTimeout(kick,180);setTimeout(kick,600)},{once:true})});setTimeout(kick,120);setTimeout(kick,450);setTimeout(kick,900);setTimeout(kick,1500)}if(q.audioUrl)startAudioSegment(q);showCountdown(()=>{if(q.audioUrl)startAudioSegment(q);if(q.videoId){const v=getMediaVolume(q);postYoutubeVolume(v);postYoutubeUnmute();postYoutubePlay();setTimeout(()=>{postYoutubeUnmute();postYoutubePlay();postYoutubeVolume(v)},180);setTimeout(()=>{postYoutubeUnmute();postYoutubePlay()},650)}})}
function hostQuestion(d){clearInterval(timer);applyTheme(window.__roomQuizTheme||{});const q=d.question;window.__currentQ=q;const colors=q.colors&&q.colors.length===4?q.colors:COLORS;const counts=d.answerCounts||[];const raidBattle=!!q.raidEnabled;const raidFx=raidBattle?`<div class="raid-battle-fx" aria-hidden="true"><div class="raid-boss-seal">👑<span>RAID</span></div><div class="raid-battle-chain rb1">⛓️⛓️⛓️</div><div class="raid-battle-chain rb2">⛓️⛓️⛓️</div><div class="raid-battle-chain rb3">⛓️⛓️</div><div class="raid-battle-chain rb4">⛓️⛓️</div><div class="raid-battle-chain rb5">⛓️⛓️⛓️</div><div class="raid-battle-chain rb6">⛓️⛓️⛓️</div><div class="raid-battle-vignette"></div></div>`:'';app.innerHTML=`<div class="wrap ${raidBattle?'raid-battle-screen':''}">${raidFx}<div class="top"><div><b>LIVE HOST VIEW</b> <button class="secondary" onclick="socket.emit('host:skip')">⏭ 건너뛰기</button><button class="secondary" onclick="unlockAudio()">🔊 소리 켜기</button></div><span class="timer host-timer"><small>남은 시간</small><strong id="tm">${q.timeLimit}</strong><em>초</em></span></div><div class="card"><h1>${esc(q.prompt)}</h1>${media(q,false,false)}${playerVolumeControl(q)}</div>${q.options?.length?`<div class="host-choice-grid">${q.options.map((o,i)=>`<div class="host-choice" style="--answer-color:${colors[i]||COLORS[i]}"><b>${String.fromCharCode(65+i)}</b><span>${esc(o)}</span><strong id="hc${i}">${counts[i]||0}</strong><small>명</small></div>`).join('')}</div>`:''}<div class="card host-stats"><b>응답 <span id="hostAnswered">${d.answerCount||0}/${d.participants?.length||0}</span></b><p class="muted">정답/오답은 문제 종료 후 공개됩니다. 아래에서 참가자의 현재 선택을 실시간으로 볼 수 있습니다.</p><div id="hostAnswers" class="host-answers"></div></div></div>`;if(q.audioUrl)startAudioSegment(q);if(q.videoId){const kick=()=>{postYoutubeVolume(getMediaVolume(q));postYoutubeUnmute();postYoutubePlay()};document.querySelectorAll('.card iframe').forEach(f=>{f.addEventListener('load',()=>{kick();setTimeout(kick,180);setTimeout(kick,600)},{once:true})});setTimeout(kick,120);setTimeout(kick,450);setTimeout(kick,900);setTimeout(kick,1500)}const end=Date.now()+q.timeLimit*1000;timer=setInterval(()=>{const x=Math.max(0,(end-Date.now())/1000),e=document.getElementById('tm'),box=e?.closest('.timer'),sec=Math.ceil(x);if(e)e.textContent=sec;if(box){box.classList.toggle('urgent',sec<=5&&sec>0);box.classList.toggle('danger',sec<=3&&sec>0)}if(x<=0){clearInterval(timer);socket.emit('question:timeoutCheck',{index:d.index})}},100)}
function renderHostAnswers(items){const el=document.getElementById('hostAnswers');if(!el)return;el.innerHTML=(items||[]).map(x=>`<div class="host-answer-row"><b>${esc(x.nickname)}</b><span>${esc(Array.isArray(x.answer)?x.answer.join(', '):String(x.answer??'미응답'))}</span><em>${x.changed?'변경':''}</em></div>`).join('')||'<p class="muted">아직 답변한 참가자가 없습니다.</p>'}
function buttons(q){const colors=q.colors&&q.colors.length===4?q.colors:COLORS;if(q.type==='subjective')return `<div class="card subjective-submit"><input id="sub" autocomplete="off" placeholder="답을 입력하세요" oninput="subjectiveInput(this)" onkeydown="if(event.key==='Enter'&&!event.isComposing){event.preventDefault();submitSubjective()}"><button id="subBtn" class="submit-answer" onclick="submitSubjective()" disabled>제출</button><p id="subStatus" class="muted">답을 입력하면 제출할 수 있습니다. Enter 키로도 제출할 수 있어요.</p></div>`;if(q.type==='ordering'){const opts=q.options||[];window.orderSelected=[];return `<div class="card ordering-answer-card"><p class="ordering-help">각 칸에서 순서를 하나씩 선택하세요.</p><div class="ordering-answer-grid">${opts.map((o,i)=>`<label class="order-answer-slot"><span>${i+1}번째</span><select id="ord${i}" onchange="setOrderSlot(${i},this.value)"><option value="">선택</option>${opts.map((x,k)=>`<option value="${k+1}">${k+1}. ${esc(x)}</option>`).join('')}</select></label>`).join('')}</div><button class="secondary" onclick="submitOrdering()">순서 제출</button><p id="ordStatus" class="muted">모든 칸을 채운 뒤 제출하세요.</p></div>`}if(q.type==='multiple'){window.multiSelected=[];return `<div class="multi-grid">${(q.options||[]).map((o,i)=>`<button class="answer multi-answer" data-index="${i}" style="--answer-color:${colors[i]||COLORS[i]||COLORS[0]}" onclick="toggleMulti(${i},this)">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><button class="secondary" onclick="submitMulti()">선택한 답 제출</button><p id="multiStatus" class="muted">복수 선택: 여러 개를 고른 뒤 제출하세요.</p>`}if(q.type==='ox'){const ox=['O','X'];return `<div class="ox-answer-grid">${ox.map((o,i)=>`<button class="ox-answer ${o==='O'?'ox-o':'ox-x'}" id="ansopt${i}" onclick="sendOption(${i})"><strong>${o}</strong><span>${o==='O'?'그렇다':'아니다'}</span></button>`).join('')}</div><p id="oxStatus" class="muted ox-status">O 또는 X를 선택하세요.</p>`}return (q.options||[]).map((o,i)=>`<button class="answer" id="ansopt${i}" style="--answer-color:${colors[i]||COLORS[i]||COLORS[0]}" onclick="sendOption(${i})">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}
function subjectiveInput(el){const b=document.getElementById('subBtn'),st=document.getElementById('subStatus');if(!b)return;const value=el.value.trim(),has=value.length>0,changed=has&&value!==String(window.__submittedSubjective||'');if(locked&&allowAnswerChange){b.disabled=!changed;b.classList.toggle('modified',changed);b.classList.toggle('submitted-btn',!changed);b.textContent=changed?'수정 제출':'제출 완료';if(st)st.textContent=changed?'수정된 답안입니다. 수정 제출을 눌러주세요.':'현재 제출한 답안입니다. 답을 수정하면 다시 제출할 수 있습니다.';return}b.disabled=!has;b.classList.remove('submitted-btn','modified');b.textContent=has?'제출':'제출';if(st)st.textContent=has?'입력 완료 · 제출 버튼을 눌러주세요.':'답을 입력하면 제출할 수 있습니다.'}function submitSubjective(){const el=document.getElementById('sub'),b=document.getElementById('subBtn'),st=document.getElementById('subStatus');if(!el||!el.value.trim()||!b)return;if(locked&&!allowAnswerChange)return;const answer=el.value.trim();const wasLocked=locked; b.disabled=true;b.classList.remove('modified');b.textContent='제출 중…';if(st)st.textContent='서버에 답안을 저장하는 중입니다…';socket.timeout(5000).emit('player:answer',{answer},(err,res)=>{if(err||!res?.ok){if(!wasLocked)locked=false;b.disabled=false;b.textContent='제출';b.classList.remove('submitted-btn');if(st)st.textContent='제출에 실패했습니다. 다시 눌러주세요.';return}window.__submittedSubjective=answer;locked=true;b.disabled=false;b.classList.add('submitted-btn');b.textContent='제출 완료';if(st)st.textContent=allowAnswerChange?'제출 완료 · 답을 수정하면 다시 제출할 수 있습니다.':'제출 완료 · 결과는 문제 종료 후 공개됩니다.'})}window.multiSelected=[];function toggleMulti(i,b){if(locked&&!allowAnswerChange)return;const n=window.multiSelected.indexOf(i);if(n>=0){window.multiSelected.splice(n,1);b.classList.remove('selected')}else{window.multiSelected.push(i);b.classList.add('selected')}const st=document.getElementById('multiStatus');if(st)st.textContent=`선택 ${window.multiSelected.length}개 · 선택한 답 제출을 눌러주세요.`}function submitMulti(){if(!window.multiSelected.length)return alert('정답을 하나 이상 선택해주세요.');if(locked&&!allowAnswerChange)return;const answer=window.multiSelected.map(i=>currentQuestionOptions[i]);locked=true;socket.timeout(5000).emit('player:answer',{answer},(err,res)=>{const st=document.getElementById('multiStatus');if(err||!res?.ok){locked=false;if(st)st.textContent='제출에 실패했습니다. 다시 눌러주세요.';return}if(st)st.textContent=allowAnswerChange?'답변이 저장되었습니다. 제한시간 동안 다시 선택할 수 있습니다.':'답변이 제출되었습니다. 결과는 문제 종료 후 공개됩니다.'})}function sendOption(i){if(locked&&!allowAnswerChange)return;document.querySelectorAll('.answer,.ox-answer').forEach(b=>b.classList.remove('selected'));const b=document.getElementById('ansopt'+i);if(b)b.classList.add('selected');locked=true;socket.timeout(5000).emit('player:answer',{answer:currentQuestionOptions[i]},(err,res)=>{if(err||!res?.ok){locked=false;if(b)b.classList.remove('selected');return}const st=document.getElementById('oxStatus');if(st)st.textContent='선택한 답이 제출되었습니다.'})}let currentQuestionOptions=[];let allowAnswerChange=false;window.orderSelected=[];function setOrderSlot(i,v){window.orderSelected[i]=v?Number(v):null;const st=document.getElementById('ordStatus');if(st)st.textContent=`선택 ${window.orderSelected.filter(Boolean).length}/${currentQuestionOptions.length}칸`; }function submitOrdering(){if(locked&&!allowAnswerChange)return;const n=currentQuestionOptions.length;if(window.orderSelected.length!==n||window.orderSelected.some(v=>!v))return alert('모든 순서 칸을 선택해주세요.');const uniq=new Set(window.orderSelected);if(uniq.size!==n)return alert('같은 항목을 두 번 선택할 수 없습니다.');locked=true;socket.timeout(5000).emit('player:answer',{answer:[...window.orderSelected]},(err,res)=>{const st=document.getElementById('ordStatus');if(err||!res?.ok){locked=false;if(st)st.textContent='제출에 실패했습니다. 다시 선택해주세요.';return}if(st)st.textContent='순서 답안이 제출되었습니다.'})}function send(a){if(locked&&!allowAnswerChange)return;locked=true;socket.emit('player:answer',{answer:a})}
function deathEliminatedCard(){return `<div class="death-eliminated-card"><div class="chain-art">⛓️</div><strong>탈락</strong><span>이번 문제에서 탈락했습니다.</span></div>`}
let lastPlayerResult=null;let revealPending=null;function reveal(d){clearInterval(timer);applyTheme(window.__roomQuizTheme||{});if(role==='host'){const special=d.question.fever?'fever':d.question.platinum?'platinum':'';app.innerHTML=`<div class="wrap reveal-screen ${special}"><div class="hero"><div class="logo">${d.question.fever?'🔥 FEVER TIME':d.question.platinum?'💎 PLATINUM TIME':'정답 공개'}</div><p class="muted">정답: ${esc(Array.isArray(d.correctAnswer)?d.correctAnswer.join(', '):d.correctAnswer)}</p><h1>${esc(Array.isArray(d.correctAnswer)?d.correctAnswer.join(', '):d.correctAnswer)}</h1>${d.question.revealEnabled?media({...d.question,showVideo:true},true):''}</div></div>`;return}if(d.index!==currentQuestionIndex)return;const r=d.playerResult||lastPlayerResult||revealPending;const submitted=d.submitted===true||!!r;const ok=submitted&&r?!!r.correct:null;const myScore=r?+(r.points||0):0;const status=submitted?(ok?`정답! ${myScore>=0?'+':''}${myScore}점`:`오답 · ${myScore}점`):'미응답 · 0점';if(d.raid?.enabled&&role!=='host'){const lead=d.raid.leaders||[];const title=d.raid.success?'👑 RAID SUCCESS':'💥 RAID FAILED';const names=d.raid.success&&lead.length?lead.map((x,i)=>`<div class="raid-leader rank-${i+1}"><b>${i+1}위</b>${avatarMarkup(x.avatar||'🦊','raid-avatar')}<span>${esc(x.nickname)}</span><strong>${x.points}점</strong></div>`).join(''):'<p class="muted">이번 레이드의 명단은 표시되지 않습니다.</p>';setTimeout(()=>{const box=document.querySelector('.reveal-screen .hero');if(box){const el=document.createElement('div');el.className='raid-result';el.innerHTML=`<div class="raid-title">${title}</div><p>${d.raid.success?`필요 정답자 ${d.raid.threshold}명 · 정답 ${d.raid.correctCount}명`:`필요 정답자 ${d.raid.threshold}명 · 정답 ${d.raid.correctCount}명`}</p>${names}`;box.appendChild(el)}},0)}const special=d.question.fever?'fever':d.question.platinum?'platinum':'';const liveWrap=d.question.videoId?document.querySelector('.participant-yt, .audio-hidden'):null;let revealMedia='';if(d.question.revealEnabled){if(liveWrap)revealMedia='<div id="revealVideoMount" class="reveal-video-mount"></div>';else revealMedia=media({...d.question,showVideo:true},true)}app.innerHTML=`<div class="wrap reveal-screen ${special}"><div class="hero"><div class="logo">${d.question.fever?'🔥 FEVER TIME':d.question.platinum?'💎 PLATINUM TIME':'정답 공개'}</div><p id="myResult" class="result-badge ${submitted?(ok?'correct':'wrong'):''}">${esc(status)}</p><h1>${esc(Array.isArray(d.correctAnswer)?d.correctAnswer.join(', '):d.correctAnswer)}</h1>${window.__roomState?.mode==='death'&&!ok?deathEliminatedCard():revealMedia}</div></div>`;if(liveWrap&&document.getElementById('revealVideoMount')){const iframe=liveWrap.querySelector('iframe');if(iframe){liveWrap.className='yt-crop reveal-yt participant-yt';iframe.className='';document.getElementById('revealVideoMount').appendChild(liveWrap);const v=getMediaVolume(d.question);postYoutubePlay();postYoutubeUnmute();postYoutubeVolume(v);setTimeout(()=>postYoutubePlay(),100);setTimeout(()=>postYoutubeUnmute(),100);setTimeout(()=>postYoutubeVolume(v),100);setTimeout(()=>postYoutubeUnmute(),350);setTimeout(()=>postYoutubeVolume(v),350);}}if(window.__roomState?.mode==='death'){const hero=document.querySelector('.reveal-screen .hero');if(hero&&!hero.querySelector('.death-panel')){const holder=document.createElement('div');holder.innerHTML=renderDeathPanel();if(holder.firstElementChild)hero.appendChild(holder.firstElementChild)}}lastPlayerResult=null;revealPending=null}
function previewNext(d){applyTheme(window.__roomQuizTheme||{});const q=d.question||{},mode=window.__roomState?.mode||q.mode||'normal',special=q.fever?'fever':q.platinum?'platinum':'';const fire=special==='fever'?`<div class="special-fx fever-fx" aria-hidden="true"><div class="flame flame-a"></div><div class="flame flame-b"></div><div class="flame flame-c"></div><div class="fire-glow"></div></div>`:'';const diamonds=special==='platinum'?`<div class="special-fx diamond-fx" aria-hidden="true">${Array.from({length:28},(_,i)=>`<i style="--d:${i};--x:${(i*37)%100}%;--s:${8+(i%5)*3}px;--delay:${(i%9)*.28}s;--dur:${3.2+(i%6)*.45}s"></i>`).join('')}</div>`:'';const opts=[];if(q.highRisk&&mode!=='speedrun'&&mode!=='death')opts.push(`<div class="preview-option risk"><b>⚠️ HIGH RISK</b><span>5초 선택 · 도전 정답 ×2 · 도전 오답은 기본점수 감점</span></div>`);if(q.raidEnabled&&mode==='normal')opts.push(`<div class="preview-option raid"><b>👑 RAID</b><span>8지선다 · 설정한 정답자 수/비율 달성 시 성공</span></div>`);if(q.fever)opts.push(`<div class="preview-option fever-info"><b>🔥 FEVER ×2</b><span>정답 점수 ×2</span></div>`);if(q.platinum)opts.push(`<div class="preview-option platinum-info"><b>💎 PLATINUM ×3</b><span>정답 점수 ×3</span></div>`);app.innerHTML=`<div class="wrap special-preview ${special} mode-${esc(mode)}">${fire}${diamonds}<div class="hero"><div class="mode-mini-badge">${esc(modeLabel(mode))}</div><div class="logo ${q.fever?'special-fever':q.platinum?'special-platinum':''}">${q.fever?'🔥 FEVER TIME':q.platinum?'💎 PLATINUM TIME':'다음 문제'}</div><div class="big">${d.index+1}</div><h1>${esc(q.prompt)}</h1>${opts.join('')}<p class="muted">잠시 후 시작합니다.</p></div>${mode==='death'?renderDeathPanel():''}</div>`}
function primeAudio(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=window.__quizAudioCtx||(window.__quizAudioCtx=new C());if(c.state==='suspended')c.resume().catch(()=>{});window.__audioPrimed=true}catch{}}
function playRaidDoomSound(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=window.__quizAudioCtx||(window.__quizAudioCtx=new C());const run=()=>{const now=c.currentTime;const o1=c.createOscillator(),g1=c.createGain(),o2=c.createOscillator(),g2=c.createGain();o1.type='sawtooth';o1.frequency.setValueAtTime(92,now);o1.frequency.exponentialRampToValueAtTime(58,now+0.7);g1.gain.setValueAtTime(.0001,now);g1.gain.exponentialRampToValueAtTime(.16,now+.04);g1.gain.exponentialRampToValueAtTime(.0001,now+.9);o1.connect(g1);g1.connect(c.destination);o2.type='sine';o2.frequency.setValueAtTime(46,now+.18);o2.frequency.exponentialRampToValueAtTime(30,now+1.15);g2.gain.setValueAtTime(.0001,now+.18);g2.gain.exponentialRampToValueAtTime(.12,now+.24);g2.gain.exponentialRampToValueAtTime(.0001,now+1.25);o2.connect(g2);g2.connect(c.destination);o1.start(now);o1.stop(now+.95);o2.start(now+.18);o2.stop(now+1.3)};if(c.state==='suspended')c.resume().then(run).catch(()=>{});else run()}catch{}}
function beep(freq=660,duration=.08){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=window.__quizAudioCtx||(window.__quizAudioCtx=new C());const o=c.createOscillator(),g=c.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.045,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+duration)}catch{}}
function postYoutubeCommand(func,args=[]){document.querySelectorAll('iframe').forEach(f=>{try{f.contentWindow.postMessage(JSON.stringify({event:'command',func,args}),'*')}catch{}})}function postYoutubePlay(){postYoutubeCommand('playVideo')}function postYoutubeMute(){postYoutubeCommand('mute')}function postYoutubeUnmute(){postYoutubeCommand('unMute')}
function showCountdown(done){const old=document.getElementById('countdownOverlay');if(old)old.remove();const el=document.createElement('div');el.id='countdownOverlay';el.className='countdown-overlay';el.innerHTML='<div class="countdown-number">3</div>';document.body.appendChild(el);let n=3;const tick=()=>{if(!document.getElementById('countdownOverlay'))return;if(n<=0){el.classList.add('countdown-out');setTimeout(()=>el.remove(),260);if(typeof done==='function')done();return}el.querySelector('.countdown-number').textContent=n;beep(n===1?880:660,.09);el.querySelector('.countdown-number').classList.remove('countdown-pop');void el.querySelector('.countdown-number').offsetWidth;el.querySelector('.countdown-number').classList.add('countdown-pop');n--;setTimeout(tick,420)};tick()}
function startAudioSegment(q){if(!q.audioUrl)return;const a=document.getElementById('qAudio');if(!a)return;const st=Math.max(0,Number(q.start)||0),en=Math.max(0,Number(q.end)||0);a.volume=getMediaVolume(q)/100;const play=()=>{try{a.currentTime=st;const p=a.play();if(p)p.catch(()=>{})}catch{}};a.onloadedmetadata=play;a.ontimeupdate=()=>{if(en>st&&a.currentTime>=en){a.pause();a.currentTime=st}};play()}function unlockAudio(){document.querySelectorAll('iframe').forEach(f=>{try{f.contentWindow.postMessage(JSON.stringify({event:'command',func:'setVolume',args:[getMediaVolume(window.__currentQ)]}),'*');f.contentWindow.postMessage(JSON.stringify({event:'command',func:'unMute',args:[]}),'*');f.contentWindow.postMessage(JSON.stringify({event:'command',func:'playVideo',args:[]}),'*')}catch{}});const a=document.getElementById('qAudio');if(a){const st=Math.max(0,Number(window.__currentQ?.start)||0);a.volume=getMediaVolume(window.__currentQ)/100;try{a.currentTime=st;a.play()}catch{}}document.querySelectorAll('.sound-btn').forEach(b=>b.textContent='🔊 소리 활성화됨')}
function finished(d){clearInterval(timer);lastGameFinished=d;sessionStorage.removeItem('quiz-live-room');sessionStorage.removeItem('quiz-live-nickname');sessionStorage.removeItem('quiz-live-reconnect');const mode=d.mode||window.__roomState?.mode||'normal',top=d.noWinner?null:d.results?.[0];const teamBox=mode==='team'&&d.teamResults?`<div class=\"team-final-grid\"><section class=\"card team-final-card red-team\"><div class=\"team-final-head\"><h2>🔴 RED TEAM</h2><strong>${d.teamResults.red.reduce((a,x)=>a+x.score,0)}점</strong></div>${d.teamResults.red.map(x=>`<div class=\"team-final-row\"><b>#${x.teamRank}</b>${avatarMarkup(x.avatar||'🦊','ranking-avatar')}<span>${esc(x.nickname)}</span><strong>${x.score}점</strong></div>`).join('')||'<p class=\"muted\">참가자 없음</p>'}</section><section class=\"card team-final-card blue-team\"><div class=\"team-final-head\"><h2>🔵 BLUE TEAM</h2><strong>${d.teamResults.blue.reduce((a,x)=>a+x.score,0)}점</strong></div>${d.teamResults.blue.map(x=>`<div class=\"team-final-row\"><b>#${x.teamRank}</b>${avatarMarkup(x.avatar||'🦊','ranking-avatar')}<span>${esc(x.nickname)}</span><strong>${x.score}점</strong></div>`).join('')||'<p class=\"muted\">참가자 없음</p>'}</section></div>`:'';app.innerHTML=`<div class=\"wrap results-screen mode-${esc(mode)}\"><div class=\"mode-hero mode-${esc(mode)}\"><div class=\"mode-emblem\">${mode==='death'?'☠️':mode==='speedrun'?'⚡':mode==='team'?'🔴🔵':'🏆'}</div><div class=\"mode-title\">${d.noWinner?'우승자 없음':'경기 종료'}</div><p>${esc(d.title||'QUIZ LIVE')} · ${esc(modeLabel(mode))}</p>${d.noWinner?'<strong class=\"no-winner\">모든 참가자가 탈락했습니다.</strong>':''}</div>${top&&mode!=='team'?`<div class=\"winner-card\"><div class=\"winner-crown\">👑</div><div class=\"winner-rank\">1st</div><div class=\"winner-avatar\">${avatarMarkup(top.avatar||'🦊','winner-avatar-img')}</div><h1>${esc(top.nickname)}</h1><strong>${top.score}점</strong><p class=\"muted\">정답 ${top.correctCount||0} · 정확도 ${top.accuracy||0}%</p></div>`:''}${teamBox}<div class=\"card final-ranking\">${(d.results||[]).map(x=>`<div class=\"rank ${x.eliminated?'eliminated-row':''}\"><b>#${x.rank||'-'}</b><span>${avatarMarkup(x.avatar||'🦊','ranking-avatar')} ${esc(x.nickname)} <small class=\"muted\">정답 ${x.correctCount||0} · ${x.accuracy||0}%${x.eliminated?' · 탈락':''}</small></span><b>${x.score}점</b></div>`).join('')}</div><div class=\"card results-actions\"><h3>📊 경기 통계</h3><p class=\"muted\">총 ${Array.isArray(d.history)?d.history.length:0}문제의 응답 기록이 있습니다.</p>${role==='host'?'<button onclick=\"showAdvancedStats()\">📈 고급 통계 보기</button>':''}</div><div style=\"text-align:center;margin:24px 0\"><button onclick=\"home()\">🏠 홈으로</button></div></div>`}
function showAdvancedStats(){const d=lastGameFinished;if(!d)return;const hist=d.history||[],players=d.results||[];const rows=hist.map((h,i)=>{const ps=h.players||[],submitted=ps.filter(x=>x.submitted).length,correct=ps.filter(x=>x.correct).length,times=ps.filter(x=>x.submitted).map(x=>x.elapsed).filter(x=>x>0);return{i:i+1,rate:ps.length?Math.round(correct/ps.length*100):0,submitted,correct,avg:times.length?Math.round(times.reduce((a,b)=>a+b,0)/times.length):0}});const hardest=[...rows].sort((a,b)=>a.rate-b.rate).slice(0,5),fastest=[...rows].sort((a,b)=>a.avg-b.avg).filter(x=>x.avg>0).slice(0,5);app.innerHTML=`<div class="wrap advanced-stats"><div class="top"><div><h1>📈 고급 통계</h1><p class="muted">${esc(d.title||'QUIZ LIVE')} · ${rows.length}문제</p></div><button class="secondary" onclick="finished(lastGameFinished)">← 결과로</button></div><div class="stats-grid"><div class="card stat-big"><b>평균 정답률</b><strong>${rows.length?Math.round(rows.reduce((a,b)=>a+b.rate,0)/rows.length):0}%</strong></div><div class="card stat-big"><b>최고 점수</b><strong>${players[0]?.score||0}</strong></div><div class="card stat-big"><b>최고 콤보</b><strong>${Math.max(0,...players.map(x=>x.maxCombo||0))}</strong></div><div class="card stat-big"><b>총 응답</b><strong>${rows.reduce((a,b)=>a+b.submitted,0)}</strong></div></div><div class="card"><h3>문제별 통계</h3><div class="table-wrap"><table><thead><tr><th>문제</th><th>정답률</th><th>응답</th><th>정답</th><th>평균 응답</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.i}</td><td><b>${x.rate}%</b></td><td>${x.submitted}</td><td>${x.correct}</td><td>${x.avg?x.avg+'ms':'-'}</td></tr>`).join('')}</tbody></table></div></div><div class="stats-two"><div class="card"><h3>🔥 가장 어려운 문제</h3>${hardest.map(x=>`<div class="stat-row"><b>Q${x.i}</b><span>${x.rate}% 정답</span></div>`).join('')||'<p class="muted">데이터 없음</p>'}</div><div class="card"><h3>⚡ 가장 빠른 문제</h3>${fastest.map(x=>`<div class="stat-row"><b>Q${x.i}</b><span>${x.avg}ms</span></div>`).join('')||'<p class="muted">데이터 없음</p>'}</div></div><div class="card"><h3>참가자별 성적</h3>${players.map(x=>`<div class="player-stat-row"><span>${avatarMarkup(x.avatar||'🦊','ranking-avatar')} ${esc(x.nickname)}</span><span>${x.score}점 · ${x.accuracy||0}% · 최고콤보 ${x.maxCombo||0}</span></div>`).join('')}</div></div>`}

async function openManage(id,token){const r=await fetch(`/api/manage/${encodeURIComponent(id)}/${encodeURIComponent(token)}`);if(!r.ok){alert('관리 링크가 만료되었거나 올바르지 않습니다.');return home()}const q=await r.json();localStorage.setItem('owner-'+id,token);q.id=id;builder(q)}
async function deleteCurrent(){if(!quiz?.id)return;const token=localStorage.getItem('owner-'+quiz.id);if(!token)return alert('관리 권한이 없습니다.');if(!confirm('이 퀴즈를 정말 삭제할까요?'))return;const r=await fetch('/api/quizzes/'+quiz.id,{method:'DELETE',headers:{'x-owner-token':token}});const d=await r.json();if(!r.ok)return alert(d.error);alert('삭제했습니다.');home()}
socket.on('host:joined',lobby);socket.on('speedrun:start',speedrunHostView);socket.on('speedrun:hostQuestion',speedrunHostQuestion);socket.on('question:raidIntro',raidIntroView);socket.on('player:joined',d=>{if(d.reconnectToken)sessionStorage.setItem('quiz-live-reconnect',d.reconnectToken);if(d.code)sessionStorage.setItem('quiz-live-room',d.code);if(d.nickname)sessionStorage.setItem('quiz-live-nickname',d.nickname);if(d.avatar){playerAvatar=d.avatar;sessionStorage.setItem('quiz-live-avatar',d.avatar)}lobby({mode:d.mode||'normal',comboEnabled:!!d.comboEnabled,raidRules:d.raidRules||null,participants:[]})});socket.on('room:state',update);socket.on('host:answers',renderHostAnswers);socket.on('question:start',question);socket.on('question:riskChoice',d=>role==='host'?riskHostView(d):showRiskChoice(d));socket.on('speedrun:question',speedrunQuestion);socket.on('speedrun:goal',()=>{clearInterval(timer);app.innerHTML='<div class="wrap"><div class="hero"><div class="logo">🏁 GOAL</div><h1>GOAL!</h1><p class="muted">다른 참가자의 완주를 기다리는 중입니다.</p></div></div>'});socket.on('speedrun:result',()=>{});socket.on('question:reveal',reveal);socket.on('player:revealResult',r=>{lastPlayerResult=r;revealPending=r;if(document.getElementById('myResult')&&currentQuestionIndex>=0){const ok=!!r.correct;document.getElementById('myResult').textContent=ok?`정답! +${+(r.points||0)}점`:'오답 · 0점';document.getElementById('myResult').className='result-badge '+(ok?'correct':'wrong')}});socket.on('question:nextPreview',previewNext);socket.on('game:finished',finished);socket.on('answer:locked',()=>{const st=document.getElementById('multiStatus');if(st)st.textContent=allowAnswerChange?'답변이 저장되었습니다. 제한시간 동안 다시 선택할 수 있습니다.':'답변이 제출되었습니다. 결과는 문제 종료 후 공개됩니다.';const ans=document.getElementById('ans');if(ans)ans.classList.add('submitted');});socket.on('error:msg',alert);
(async()=>{const p=new URLSearchParams(location.search);if(p.get('manage')&&p.get('token'))return openManage(p.get('manage'),p.get('token'));const savedRoom=sessionStorage.getItem('quiz-live-room'),savedNick=sessionStorage.getItem('quiz-live-nickname'),savedToken=sessionStorage.getItem('quiz-live-reconnect');if(savedRoom&&savedNick){role='player';code=savedRoom;return socket.connected?reconnectPlayer():null}if(p.get('room'))return joinPage(p.get('room'));if(p.get('quiz')){const r=await fetch('/api/quiz/'+p.get('quiz'));if(r.ok){const q=await r.json();app.innerHTML=`<div class="wrap"><div class="hero"><div class="logo">QUIZ <span>LIVE</span></div><h1>${esc(q.title)}</h1></div><div class="card join-card"><input id="jc" placeholder="방 코드" inputmode="numeric" maxlength="6"><div class="field"><input id="jn" placeholder="닉네임" maxlength="20"></div>${avatarPicker()}<button onclick="join()">참가하기</button></div></div>`}}})();